// "execute" function parameters
// none

// "Annuity" contract constructor parameters
<executor_allowance> // int = <0xdc05>
<installment> // int = <0x1027>
<recipient_locking_bytecode> // bytes25 = <0x76a9145ad61b729b4170216bf57cd02c606ca52d13b89a88ac>
<period> // int = <0x01>
